{
    "name": "015_audio_sinusoidal_position_embedding_with_conv_projection",
    "hf_id": "Qwen/Qwen3-Omni-30B-A3B-Instruct",
    "description": "Audio encoder's sinusoidal position embedding generation followed by 3-stage Conv2d downsampling (8x total reduction), GELU activations, and linear projection to model dimension. Processes mel-spectrogram through conv layers, adds cached sinusoidal position embeddings, and returns padded output.",
    "axes": {
        "batch_size": {
            "type": "var",
            "description": "Number of audio samples in batch"
        },
        "time_dim": {
            "type": "var",
            "description": "Time dimension of mel-spectrogram input"
        },
        "time_after_conv": {
            "type": "var",
            "description": "Time dimension after 3 stride-2 convolutions (approximately time_dim // 8)"
        },
        "d_model": {
            "type": "const",
            "value": 1024,
            "description": "Model hidden dimension"
        },
        "num_mel_bins": {
            "type": "const",
            "value": 80,
            "description": "Number of mel frequency bins"
        },
        "max_source_positions": {
            "type": "const",
            "value": 1500,
            "description": "Maximum sequence length for position embeddings"
        },
        "downsample_hidden_size": {
            "type": "const",
            "value": 384,
            "description": "Hidden size in conv layers"
        },
        "freq_dim_after_conv": {
            "type": "const",
            "value": 10,
            "description": "Frequency dimension after 3 stride-2 convs: 80->40->20->10"
        },
        "conv_out_dim": {
            "type": "const",
            "value": 3840,
            "description": "Flattened conv output: 384 * 10"
        },
        "one": {
            "type": "const",
            "value": 1,
            "description": "Constant 1 for input channel dimension"
        },
        "kernel_size": {
            "type": "const",
            "value": 3,
            "description": "Conv kernel size"
        }
    },
    "custom_inputs_entrypoint": "get_inputs",
    "inputs": {
        "input_features": {
            "shape": [
                "batch_size",
                "one",
                "num_mel_bins",
                "time_dim"
            ],
            "dtype": "bfloat16",
            "description": "Mel-spectrogram input"
        },
        "conv2d1_weight": {
            "shape": [
                "downsample_hidden_size",
                "one",
                "kernel_size",
                "kernel_size"
            ],
            "dtype": "bfloat16",
            "description": "First conv layer weights"
        },
        "conv2d1_bias": {
            "shape": [
                "downsample_hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "First conv layer bias"
        },
        "conv2d2_weight": {
            "shape": [
                "downsample_hidden_size",
                "downsample_hidden_size",
                "kernel_size",
                "kernel_size"
            ],
            "dtype": "bfloat16",
            "description": "Second conv layer weights"
        },
        "conv2d2_bias": {
            "shape": [
                "downsample_hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Second conv layer bias"
        },
        "conv2d3_weight": {
            "shape": [
                "downsample_hidden_size",
                "downsample_hidden_size",
                "kernel_size",
                "kernel_size"
            ],
            "dtype": "bfloat16",
            "description": "Third conv layer weights"
        },
        "conv2d3_bias": {
            "shape": [
                "downsample_hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Third conv layer bias"
        },
        "conv_out_weight": {
            "shape": [
                "d_model",
                "conv_out_dim"
            ],
            "dtype": "bfloat16",
            "description": "Linear projection weights"
        },
        "positional_embedding": {
            "shape": [
                "max_source_positions",
                "d_model"
            ],
            "dtype": "bfloat16",
            "description": "Cached sinusoidal position embeddings"
        },
        "embed_scale": {
            "shape": null,
            "dtype": "float32",
            "description": "Embedding scale factor sqrt(d_model)"
        }
    },
    "outputs": {
        "hidden_states": {
            "shape": [
                "batch_size",
                "time_after_conv",
                "d_model"
            ],
            "dtype": "bfloat16",
            "description": "Output embeddings with position encoding added"
        }
    },
    "reference": "import math\n\nimport torch\nimport torch.nn.functional as F\n\n\ndef get_inputs(axes_and_scalars: dict, device: torch.device) -> dict[str, torch.Tensor]:\n    batch_size = axes_and_scalars[\"batch_size\"]\n    time_dim = axes_and_scalars[\"time_dim\"]\n    d_model = 1024\n    max_source_positions = 1500\n    downsample_hidden_size = 384\n    conv_out_dim = 3840  # 384 * 10\n    kernel_size = 3\n    dtype = torch.bfloat16\n\n    g = torch.Generator(device=device)\n    g.manual_seed(42)\n\n    def kaiming_conv(out_c, in_c, kh, kw):\n        fan_in = in_c * kh * kw\n        return (torch.randn(out_c, in_c, kh, kw, device=device, generator=g) * math.sqrt(2.0 / fan_in)).to(dtype)\n\n    def xavier(out_f, in_f):\n        return (torch.randn(out_f, in_f, device=device, generator=g) / math.sqrt(in_f)).to(dtype)\n\n    # Sinusoidal positional embedding\n    pe = torch.zeros(max_source_positions, d_model, device=device)\n    position = torch.arange(0, max_source_positions, device=device).unsqueeze(1).float()\n    div_term = torch.exp(torch.arange(0, d_model, 2, device=device).float() * -(math.log(10000.0) / d_model))\n    pe[:, 0::2] = torch.sin(position * div_term)\n    pe[:, 1::2] = torch.cos(position * div_term)\n\n    return {\n        \"input_features\": torch.randn(batch_size, 1, 80, time_dim, device=device, generator=g).to(dtype),\n        # Conv weights \u2014 Kaiming init\n        \"conv2d1_weight\": kaiming_conv(downsample_hidden_size, 1, kernel_size, kernel_size),\n        \"conv2d1_bias\": torch.randn(downsample_hidden_size, device=device, generator=g).to(dtype),\n        \"conv2d2_weight\": kaiming_conv(downsample_hidden_size, downsample_hidden_size, kernel_size, kernel_size),\n        \"conv2d2_bias\": torch.randn(downsample_hidden_size, device=device, generator=g).to(dtype),\n        \"conv2d3_weight\": kaiming_conv(downsample_hidden_size, downsample_hidden_size, kernel_size, kernel_size),\n        \"conv2d3_bias\": torch.randn(downsample_hidden_size, device=device, generator=g).to(dtype),\n        # Linear projection weight\n        \"conv_out_weight\": xavier(d_model, conv_out_dim),\n        # Sinusoidal positional embedding\n        \"positional_embedding\": pe.to(dtype),\n        # embed_scale = sqrt(d_model)\n        \"embed_scale\": math.sqrt(d_model),\n    }\n\n\n@torch.no_grad()\ndef run(\n    input_features: torch.Tensor,\n    conv2d1_weight: torch.Tensor,\n    conv2d1_bias: torch.Tensor,\n    conv2d2_weight: torch.Tensor,\n    conv2d2_bias: torch.Tensor,\n    conv2d3_weight: torch.Tensor,\n    conv2d3_bias: torch.Tensor,\n    conv_out_weight: torch.Tensor,\n    positional_embedding: torch.Tensor,\n    embed_scale: float,\n):\n    # Stage 1: Conv2d (1 -> 384 channels) + GELU\n    x = F.conv2d(input_features, conv2d1_weight, conv2d1_bias, stride=2, padding=1)\n    x = F.gelu(x)\n    \n    # Stage 2: Conv2d (384 -> 384 channels) + GELU\n    x = F.conv2d(x, conv2d2_weight, conv2d2_bias, stride=2, padding=1)\n    x = F.gelu(x)\n    \n    # Stage 3: Conv2d (384 -> 384 channels) + GELU\n    x = F.conv2d(x, conv2d3_weight, conv2d3_bias, stride=2, padding=1)\n    x = F.gelu(x)\n    \n    # Reshape: (batch, channels, freq, time) -> (batch, time, channels*freq)\n    b, c, f, t = x.size()\n    x = x.permute(0, 3, 1, 2).contiguous().view(b, t, c * f)\n    \n    # Linear projection to d_model (no bias)\n    x = F.linear(x, conv_out_weight)\n    \n    # Scale embeddings\n    x = x * embed_scale\n    \n    # Add positional embeddings\n    seq_len = x.shape[1]\n    pos_embed = positional_embedding[:seq_len, :].unsqueeze(0)\n    x = x + pos_embed\n    \n    return x\n"
}

